package com.aistock.prediction.analysis;
import com.aistock.common.BusinessException;import com.aistock.prediction.explanation.*;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import java.time.*;import java.util.*;import org.springframework.http.HttpStatus;
public final class AnalysisService {
 private final AnalysisRepository records;private final AnalysisMarketClient market;private final MaasClient client;private final ObjectMapper m;private final Clock clock;private final AnalysisPredictionSource predictions;private final com.aistock.prediction.marketuse.MarketUseOwnerService marketUses;
 public AnalysisService(AnalysisRepository records,AnalysisMarketClient market,MaasClient client,ObjectMapper m,Clock clock){this(records,market,client,m,clock,null);}
 public AnalysisService(AnalysisRepository records,AnalysisMarketClient market,MaasClient client,ObjectMapper m,Clock clock,AnalysisPredictionSource predictions){this(records,market,client,m,clock,predictions,null);}
 public AnalysisService(AnalysisRepository records,AnalysisMarketClient market,MaasClient client,ObjectMapper m,Clock clock,AnalysisPredictionSource predictions,com.aistock.prediction.marketuse.MarketUseOwnerService marketUses){this.marketUses=marketUses;this.records=records;this.market=market;this.client=client;this.m=m;this.clock=clock;this.predictions=predictions;}
 public JsonNode generate(UUID user,AnalysisInput in){if(in==null||in.operationId()==null||in.marketVersionId()==null)throw invalid();validate(in.instrumentId(),in.from(),in.to(),1);var prior=records.replay(user,in,clock.instant());if(prior!=null)return prior;if(!client.enabled())throw new BusinessException("AI_NOT_CONFIGURED","AI分析未配置，行情仍可查看",HttpStatus.SERVICE_UNAVAILABLE);var admission=records.begin(user,in,clock.instant());if(!admission.execute())return admission.receipt();
 try(var scope=marketUses==null?com.aistock.prediction.marketuse.MarketUseContext.empty():marketUses.acquire(in.operationId(),admission.generation())){return generateAdmitted(user,in,admission);}
 catch(BusinessException e){records.complete(in.operationId(),admission.generation(),null,e.code(),clock.instant());throw e;}
 finally{if(marketUses!=null)marketUses.notifyCompleted(in.operationId(),admission.generation());}
 }
 private JsonNode generateAdmitted(UUID user,AnalysisInput in,AnalysisRepository.Claim admission){
 AnalysisPredictionSource.Reference ref;AnalysisFacts.Facts facts;
 try{ref=in.predictionId()==null?null:source().read(user,in.instrumentId(),in.predictionId());facts=AnalysisFacts.build(market.evidence(in.instrumentId(),in.from(),in.to(),in.marketVersionId()),client.model(),m);if(ref!=null)facts=AnalysisPredictionFacts.combine(facts,in.predictionId(),ref,client.model(),m);}
 catch(BusinessException e){records.complete(in.operationId(),admission.generation(),null,e.code(),clock.instant());throw e;}
 catch(RuntimeException e){records.complete(in.operationId(),admission.generation(),null,"ANALYSIS_EVIDENCE_UNAVAILABLE",clock.instant());throw new BusinessException("ANALYSIS_EVIDENCE_UNAVAILABLE","行情依据暂不可用，已有分析保留",HttpStatus.SERVICE_UNAVAILABLE);}
 AnalysisRepository.Claim claim;
 try{claim=records.bindFacts(in.operationId(),admission.generation(),facts,clock.instant());}
 catch(BusinessException e){records.complete(in.operationId(),admission.generation(),null,e.code(),clock.instant());throw e;}
 if(!claim.execute())return claim.receipt();JsonNode paragraphs=null;String error=null;try{var raw=client.generateAnalysis(facts.values());paragraphs=ExplanationTemplate.render(raw,facts.values(),m);for(var part:raw.path("paragraphs")){String plain=part.path("template").asText().replaceAll("\\{\\{[A-Z][A-Z0-9_]{0,31}\\}\\}","");if(java.util.regex.Pattern.compile("金叉|死叉|突破|跌破|穿越|实时|即时").matcher(plain).find())throw new BusinessException("AI_OUTPUT_INVALID","AI分析含未核验的行情结论",HttpStatus.UNPROCESSABLE_ENTITY);}for(var p:raw.path("paragraphs")){var refs=new HashSet<String>();p.path("refs").forEach(x->refs.add(x.asText()));if("overview".equals(p.path("kind").asText())&&!refs.containsAll(Set.of("STOCK","AS_OF"))||"risk".equals(p.path("kind").asText())&&!refs.containsAll(Set.of("BASIS_LIMIT","FRESHNESS_LIMIT"))||"readout".equals(p.path("kind").asText())&&Collections.disjoint(refs,Set.of("MA5_STATE","MACD_STATE","RSI_STATE")))throw AnalysisFacts.invalid();if(ref!=null){if("readout".equals(p.path("kind").asText())&&!refs.containsAll(Set.of("PRED_ORIGIN_DATE","PRED_TREND","PRED_RELATIVE_ORIGIN","PRED_VERIFICATION"))||"risk".equals(p.path("kind").asText())&&!refs.containsAll(Set.of("PRED_LIMIT","PRED_CONTEXT_RELATION")))throw new BusinessException("AI_OUTPUT_INVALID","预测引用未通过核验",HttpStatus.UNPROCESSABLE_ENTITY);}}}catch(BusinessException e){paragraphs=null;error=e.code();}catch(RuntimeException e){paragraphs=null;error="AI_UNAVAILABLE";}return records.complete(in.operationId(),admission.generation(),paragraphs,error,clock.instant());}
 private AnalysisPredictionSource source(){if(predictions==null)throw invalid();return predictions;}
 public JsonNode options(UUID user,String id,int page){return source().options(user,id,page);}
 public JsonNode list(UUID user,String id,LocalDate from,LocalDate to,int page){validate(id,from,to,page);var n=(ObjectNode)records.list(user,id,from,to,page,clock.instant());n.put("configured",client.enabled());return n;}
 public JsonNode get(UUID user,UUID id){return records.get(user,id);}
 private void validate(String id,LocalDate from,LocalDate to,int page){if(id==null||!id.matches("(SH|SZ)[0-9]{6}")||from==null||to==null||from.isAfter(to)||to.isAfter(LocalDate.now(clock.withZone(ZoneId.of("Asia/Shanghai"))))||from.isBefore(to.minusMonths(12))||page<1||page>10000)throw invalid();}
 private BusinessException invalid(){return new BusinessException("AI_REQUEST_INVALID","股票、日期范围或请求编号不正确",HttpStatus.BAD_REQUEST);}
}